"""Broad fuzz generator: windows, quantifiers, aggregates, sources."""
import json, random, sys

NUM=("TIME","SIZE","COUNT")
def build(seed):
    rng=random.Random(seed)
    K=rng.randint(1,4)
    nf=rng.randint(1,3)
    fields=[]
    for i in range(nf):
        kind=rng.choice(["flag","size","count","id"])
        if kind=="flag": fields.append({"name":"f%d"%i,"type":"FLAG"})
        elif kind=="id": fields.append({"name":"f%d"%i,"type":"ID","values":["p","q","r"]})
        else: fields.append({"name":"f%d"%i,"type":kind.upper() if kind!="size" else "SIZE","min":0,"max":rng.choice([2,5,20])})
    def term(typ, allow_dollar, depth=0):
        opts=["field","const"]
        if depth<2 and typ in NUM: opts+=["scale","add","agg"]
        k=rng.choice(opts)
        if k=="field":
            cands=[f["name"] for f in fields if f["type"]==typ]
            if not cands: return None
            at = "$" if (allow_dollar and rng.random()<0.5) else rng.randrange(K)
            return {"field":rng.choice(cands),"at":at}
        if k=="const":
            if typ=="FLAG": return {"const":rng.choice([True,False]),"type":"FLAG"}
            if typ=="ID": return {"const":rng.choice(["p","q","r"]),"type":"ID"}
            return {"const":rng.randint(0,5),"type":typ}
        if k=="scale":
            c=term(typ,allow_dollar,depth+1)
            return None if c is None else {"scale":rng.choice([-1,1,2]),"term":c}
        if k=="add":
            c1=term(typ,allow_dollar,depth+1); c2=term(typ,allow_dollar,depth+1)
            return None if (c1 is None or c2 is None) else {"add":[c1,c2]}
        cands=[f["name"] for f in fields if f["type"]==typ]
        if not cands: return None
        lo=rng.randrange(K); hi=rng.randrange(lo,K)
        return {"aggregate":rng.choice(["sum","mean","min","max"]),"field":rng.choice(cands),"from":lo,"to":hi}
    atoms=[]
    for _ in range(rng.randint(0,6)):
        typ=rng.choice([f["type"] for f in fields])
        op=rng.choice(["eq","ne","lt","le","gt","ge"]) if typ in NUM else rng.choice(["eq","ne"])
        quant = rng.random()<0.4
        left=term(typ,quant); right=term(typ,quant)
        if left is None or right is None: continue
        if quant:
            lo=rng.randrange(K); hi=rng.randrange(lo,K)
            atoms.append({"quantifier":rng.choice(["any","all"]),"from":lo,"to":hi,
                          "predicate":{"cmp":op,"left":left,"right":right}})
        else:
            atoms.append({"cmp":op,"left":left,"right":right})
    def val(f):
        if f["type"]=="FLAG": return rng.choice([True,False])
        if f["type"]=="ID": return rng.choice(["p","q","r"])
        return rng.randint(f["min"], f["max"])
    def rows(n):
        out=[]; seen=set()
        for _ in range(n):
            t=rng.randint(-20,20)
            while t in seen: t+=1
            seen.add(t)
            out.append({"t":t,"values":[val(f) for f in fields]})
        return out
    def traces(prefix,ntr,nsr,maxrows):
        out=[]
        for i in range(ntr):
            out.append({"id":"%s%d"%(prefix,i),"source":"s%d"%rng.randrange(nsr),"rows":rows(rng.randint(0,maxrows))})
        return out
    return {"version":1,"schema":fields,"window":K,"atoms":atoms,
            "policy":{"max_width":rng.randint(1,4),"min_support":rng.randint(1,2),"min_witness":rng.randint(1,2)},
            "train":traces("t",rng.randint(0,3),rng.randint(1,3),rng.randint(0,8)),
            "probes":traces("p",rng.randint(0,2),1,rng.randint(0,5)),
            "queries":traces("q",rng.randint(0,2),1,rng.randint(0,6))}

if __name__=="__main__":
    print(json.dumps(build(int(sys.argv[1]))))
PYEOF
